package com.aoo.bcg.gateway;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class ConnectionResourceScopeTest{@Test void releasesHeartbeatSubscriptionBufferSessionAndChannelOnEveryClose(){var released=new ArrayList<ConnectionResourceScope.Kind>();var scope=new ConnectionResourceScope("c-1");for(var kind:ConnectionResourceScope.Kind.values())scope.own(kind,()->released.add(kind));scope.activate();scope.close();assertEquals(List.of(ConnectionResourceScope.Kind.HEARTBEAT_TASK,ConnectionResourceScope.Kind.SUBSCRIPTION,ConnectionResourceScope.Kind.BUFFER,ConnectionResourceScope.Kind.SESSION,ConnectionResourceScope.Kind.CHANNEL),released);scope.close();assertEquals(5,released.size());}@Test void activationFailsWhenBufferOrTaskOwnershipIsMissing(){var scope=new ConnectionResourceScope("c-2");scope.own(ConnectionResourceScope.Kind.CHANNEL,()->{});scope.own(ConnectionResourceScope.Kind.SESSION,()->{});assertThrows(IllegalStateException.class,scope::activate);}}
